 4 | export function createMonitorClient(options: { baseUrl: string; token: string; fetch?: typeof fetch; timeoutMs?: number }) {
 5 |   const base = options.baseUrl.replace(/\/$/, '');
 6 |   const transport = options.fetch ?? fetch;
 7 |   async function get<T>(path: string): Promise<T> {
 8 |     const response = await transport(`${base}/v1/monitor${path}`, {
 9 |       headers: { authorization: `Bearer ${options.token}` }, signal: AbortSignal.timeout(options.timeoutMs ?? 10000),
10 |       redirect: 'error', cache: 'no-store',
11 |     });
12 |     if (!response.ok) throw Object.assign(new Error(`Node monitor returned HTTP ${response.status}`), { status: response.status });
13 |     return await response.json() as T;
14 |   }
15 |   const id = (value: string) => {
16 |     if (!/^[a-f0-9]{64}$/.test(value)) throw new TypeError('A monitor observation ID is required');
17 |     return value;
18 |   };
