20 |     node: () => get<NodeSnapshot>('/node'),
21 |     tasks: (query: { status?: TaskState; q?: string; offset?: number; limit?: number } = {}) =>
22 |       get<TaskPage>(`/tasks?${new URLSearchParams(Object.entries(query).map(([key, value]) => [key, String(value)]))}`),
23 |     task: (taskId: string) => get<{ schemaVersion: string; task: TaskDetail }>(`/tasks/${id(taskId)}`),
