/** Server-side SDK. Keep the operator token on your application server. */
export function createMonitorClient(options) {
    const base = options.baseUrl.replace(/\/+$/, '');
    const transport = options.fetch ?? fetch;
    async function get(path) {
        const response = await transport(`${base}/v1/monitor${path}`, {
            headers: { authorization: `Bearer ${options.token}` }, signal: AbortSignal.timeout(options.timeoutMs ?? 10000),
            redirect: 'error', cache: 'no-store',
        });
        if (!response.ok)
            throw Object.assign(new Error(`Node monitor returned HTTP ${response.status}`), { status: response.status });
        return await response.json();
    }
    const id = (value) => {
        if (!/^[a-f0-9]{64}$/.test(value))
            throw new TypeError('A monitor observation ID is required');
        return value;
    };
    return {
        node: () => get('/node'),
        tasks: (query = {}) => {
            if (query.offset !== undefined)
                requireNonNegativeSafeInteger('tasks.offset', query.offset);
            if (query.limit !== undefined)
                requireBoundedSafeInteger('tasks.limit', query.limit, 1, 500);
            const params = new URLSearchParams();
            for (const [key, value] of Object.entries(query)) {
                if (value === undefined)
                    continue;
                params.append(key, String(value));
            }
            const qs = params.toString();
            return get(`/tasks${qs ? `?${qs}` : ''}`);
        },
        task: (taskId) => get(`/tasks/${id(taskId)}`),
        events: (taskId, after = 0, limit = 100) => {
            requireNonNegativeSafeInteger('events.after', after);
            requireBoundedSafeInteger('events.limit', limit, 1, 1000);
            return get(`/tasks/${id(taskId)}/events?after=${after}&limit=${limit}`);
        },
        models: (taskId) => get(`/tasks/${id(taskId)}/models`),
        skills: (taskId) => get(`/tasks/${id(taskId)}/skills`),
        codes: (taskId) => get(`/tasks/${id(taskId)}/codes`),
        python: (taskId) => get(`/tasks/${id(taskId)}/python`),
        code: (taskId, codeId) => get(`/tasks/${id(taskId)}/codes/${id(codeId)}`),
    };
}

